// GIVEN — do not change.
class Node {
    int info;
    Node next;

    Node(int x, Node p) {
        info = x;
        next = p;
    }

    Node(int x) {
        this(x, null);
    }
}

public class MyList {
    private Node head, tail;
    private int size;

    public boolean isEmpty() {
        return head == null;
    }

    public void addFirst(int x) {
        head = new Node(x, head);
        if (tail == null) {
            tail = head;
        }
        size++;
    }

    public void addLast(int x) {
        Node q = new Node(x);
        if (isEmpty()) {
            head = tail = q;
        } else {
            tail.next = q;
            tail = q;
        }
        size++;
    }

    public int removeFirst() {
        if (isEmpty()) {
            throw new IllegalStateException("empty list");
        }
        int x = head.info;
        head = head.next;
        if (head == null) {
            tail = null;
        }
        size--;
        return x;
    }

    public int removeLast() {
        if (isEmpty()) {
            throw new IllegalStateException("empty list");
        }
        int x = tail.info;
        if (head == tail) {
            head = tail = null;
        } else {
            Node p = head;
            while (p.next != tail) {
                p = p.next;
            }
            p.next = null;
            tail = p;
        }
        size--;
        return x;
    }
}

