// GIVEN — do not change.
class Node {
    int info;
    Node next;

    Node(int x, Node p) {
        info = x;
        next = p;
    }

    Node(int x) {
        this(x, null);
    }
}

public class MyList {
    private Node head, tail;
    private int size;

    public void addLast(int x) {
        Node q = new Node(x);
        if (head == null) {
            head = tail = q;
        } else {
            tail.next = q;
            tail = q;
        }
        size++;
    }

    // x ends up at position k (0 <= k <= size)
    public boolean insertAt(int k, int x) {
        if (k < 0 || k > size) {
            return false;
        }
        if (k == 0) {
            head = new Node(x, head);
            if (tail == null) {
                tail = head;
            }
        } else {
            Node prev = head;
            for (int i = 0; i < k - 1; i++) {
                prev = prev.next;
            }
            prev.next = new Node(x, prev.next);
            if (prev == tail) {
                tail = prev.next;
            }
        }
        size++;
        return true;
    }

    // removes the node at position k (0 <= k < size)
    public boolean deleteAt(int k) {
        if (k < 0 || k >= size) {
            return false;
        }
        if (k == 0) {
            head = head.next;
            if (head == null) {
                tail = null;
            }
        } else {
            Node prev = head;
            for (int i = 0; i < k - 1; i++) {
                prev = prev.next;
            }
            prev.next = prev.next.next;
            if (prev.next == null) {
                tail = prev;
            }
        }
        size--;
        return true;
    }
}

