// GIVEN — do not change.
class CNode {
    int info;
    CNode next;

    CNode(int x) {
        info = x;
    }
}

public class CircularList {
    private CNode tail; // tail.next is the first node

    public void addFirst(int x) {
        CNode q = new CNode(x);
        if (tail == null) {
            q.next = q;
            tail = q;
        } else {
            q.next = tail.next;
            tail.next = q;
        }
    }

    public void addLast(int x) {
        addFirst(x);
        tail = tail.next; // the new first node becomes the last one
    }

    public int removeFirst() {
        if (tail == null) {
            throw new IllegalStateException("empty list");
        }
        CNode f = tail.next;
        if (f == tail) {
            tail = null;
        } else {
            tail.next = f.next;
        }
        return f.info;
    }

    public void rotate() {
        if (tail != null) {
            tail = tail.next;
        }
    }
}

