// Grader test class (do not edit): one command per input line; after each command it prints the result and the
// state read from the REAL links of your structure (Kiem follows the fields node by node).
public class KiemTra {
    static String[] p;

    static int n(int i) {
        return Integer.parseInt(p[i]);
    }

    static String ring(CircularList t) {
        Object tail = Kiem.lay(t, "tail");
        if (tail == null) {
            return "(empty)";
        }
        return "ring " + Kiem.vong(Kiem.lay(tail, "next"), "next", "info", 1000) + " (tail " + Kiem.lay(tail, "info") + ")";
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        CircularList t = new CircularList();
        while (sc.hasNextLine()) {
            String line = sc.nextLine().trim();
            if (line.isEmpty()) {
                continue;
            }
            p = line.split("\\s+");
            String r = "ok";
            try {
                if (p[0].equals("AF")) {
                    t.addFirst(n(1));
                } else if (p[0].equals("AL")) {
                    t.addLast(n(1));
                } else if (p[0].equals("RF")) {
                    r = String.valueOf(t.removeFirst());
                } else {
                    t.rotate();
                }
            } catch (RuntimeException e) {
                r = "THROWS " + Kiem.ten(e);
            }
            System.out.println(line + " -> " + r + " | " + ring(t));
