// GIVEN — do not change.
class DNode {
    int info;
    DNode prev, next;

    DNode(int x) {
        info = x;
    }
}

public class DList {
    private DNode head, tail;

    public void addFirst(int x) {
        DNode q = new DNode(x);
        if (head == null) {
            head = tail = q;
        } else {
            q.next = head;
            head.prev = q;
            head = q;
        }
    }

    public void addLast(int x) {
        DNode q = new DNode(x);
        if (tail == null) {
            head = tail = q;
        } else {
            q.prev = tail;
            tail.next = q;
            tail = q;
        }
    }

    public int removeFirst() {
        if (head == null) {
            throw new IllegalStateException("empty list");
        }
        int x = head.info;
        head = head.next;
        if (head == null) {
            tail = null;
        } else {
            head.prev = null;
        }
        return x;
    }

    public int removeLast() {
        if (tail == null) {
            throw new IllegalStateException("empty list");
        }
        int x = tail.info;
        tail = tail.prev;
        if (tail == null) {
            head = null;
        } else {
            tail.next = null;
        }
        return x;
    }
}

